<?php use App\Core\Security;?><div class="card mb-3"><div class="card-body"><h5>گروه‌ها</h5><form method="post" action="/pricing/public/admin/groups" class="row g-2"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><div class="col"><input name="name" class="form-control" placeholder="نام گروه" required></div><div class="col"><input name="description" class="form-control" placeholder="توضیح"></div><div class="col-auto"><button class="btn btn-primary">ثبت گروه</button></div></form></div></div><?php foreach($groups as $g):?><div class="card mb-3"><div class="card-body"><form method="post" action="/pricing/public/admin/groups/<?=(int)$g['id']?>" class="row g-2 mb-3"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><div class="col-md-4"><input name="name" value="<?=Security::e($g['name'])?>" class="form-control" required></div><div class="col-md-6"><input name="description" value="<?=Security::e($g['description'])?>" class="form-control"></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">ذخیره گروه</button></div></form><form method="post" action="/pricing/public/admin/groups/<?=(int)$g['id']?>/permissions"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><div class="row"><?php foreach($permissions as $p):?><div class="col-md-4"><label><input type="checkbox" name="permissions[]" value="<?=Security::e($p['code'])?>" <?=in_array($p['code'],$g['permissions'],true)?'checked':''?>> <?=Security::e($p['name'])?></label></div><?php endforeach;?></div><button class="btn btn-sm btn-primary mt-2">ذخیره دسترسی گروه</button></form></div></div><?php endforeach;?>